messages.content:
Write a single self-contained HTML file with a 3D animation using three.js. three.js r160 is available as an ES module at './three.module.js' -- import it with:
  import * as THREE from './three.module.js';
Scene: a low-poly 3D humanoid figure performs this exact cycle on a treadmill-style ground, side-on camera: stands still for 2 seconds, walks in place for 3 seconds (limbs swinging at walking pace), runs in place for 3 seconds (faster, larger limb swings, slight forward lean), then stands still again for 2 seconds. The 10-second cycle loops forever and must start immediately on load. Limb movement must clearly differ between walking and running. No external assets besides the three.js import. Output ONLY the HTML in one code block.

response.text:
```html
<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8">
  <meta name="viewport" content="width=device-width, initial-scale=1.0">
  <title>Low-poly Humanoid Cycle</title>
  <style>
    body {
      margin: 0;
      overflow: hidden;
      font-family: sans-serif;
      background: #1a1a2e;
    }
    canvas {
      display: block;
    }
    .info {
      position: absolute;
      bottom: 20px;
      left: 20px;
      color: #aaa;
      font-size: 14px;
      background: rgba(0,0,0,0.5);
      padding: 6px 12px;
      border-radius: 8px;
      pointer-events: none;
      user-select: none;
    }
  </style>
</head>
<body>
  <div class="info">stand → walk → run → stand (10s loop)</div>

  <!-- The scene container -->
  <script type="module">
    import * as THREE from './three.module.js';

    // --- Setup scene, camera, renderer ---
    const scene = new THREE.Scene();
    scene.background = new THREE.Color(0x1a1a2e);
    scene.fog = new THREE.Fog(0x1a1a2e, 10, 30);

    const camera = new THREE.PerspectiveCamera(45, window.innerWidth / window.innerHeight, 0.1, 100);
    camera.position.set(6, 3.5, 8);
    camera.lookAt(0, 1.5, 0);

    const renderer = new THREE.WebGLRenderer({ antialias: true });
    renderer.setSize(window.innerWidth, window.innerHeight);
    renderer.shadowMap.enabled = true;
    renderer.shadowMap.type = THREE.PCFSoftShadowMap;
    document.body.appendChild(renderer.domElement);

    // --- Lighting ---
    const ambient = new THREE.AmbientLight(0x404060);
    scene.add(ambient);

    const dirLight = new THREE.DirectionalLight(0xffffff, 1.2);
    dirLight.position.set(5, 8, 5);
    dirLight.castShadow = true;
    dirLight.shadow.mapSize.width = 512;
    dirLight.shadow.mapSize.height = 512;
    dirLight.shadow.camera.near = 0.5;
    dirLight.shadow.camera.far = 20;
    dirLight.shadow.camera.left = -4;
    dirLight.shadow.camera.right = 4;
    dirLight.shadow.camera.top = 4;
    dirLight.shadow.camera.bottom = -4;
    scene.add(dirLight);

    const fillLight = new THREE.PointLight(0x4466ff, 0.4);
    fillLight.position.set(-3, 2, 3);
    scene.add(fillLight);

    // --- Ground / treadmill style ---
    const groundGeo = new THREE.BoxGeometry(8, 0.2, 3);
    const groundMat = new THREE.MeshStandardMaterial({ color: 0x3a3a4a, roughness: 0.8 });
    const ground = new THREE.Mesh(groundGeo, groundMat);
    ground.position.set(0, -0.1, 0);
    ground.receiveShadow = true;
    scene.add(ground);

    // Treadmill side rails
    const railMat = new THREE.MeshStandardMaterial({ color: 0x555566, roughness: 0.6 });
    const leftRail = new THREE.Mesh(new THREE.BoxGeometry(8, 0.15, 0.2), railMat);
    leftRail.position.set(0, 0.1, -1.5);
    leftRail.receiveShadow = true;
    scene.add(leftRail);
    const rightRail = new THREE.Mesh(new THREE.BoxGeometry(8, 0.15, 0.2), railMat);
    rightRail.position.set(0, 0.1, 1.5);
    rightRail.receiveShadow = true;
    scene.add(rightRail);

    // Treadmill belt stripes (static, low-poly)
    const stripeMat = new THREE.MeshStandardMaterial({ color: 0x6a6a7a, roughness: 0.9 });
    for (let i = -4; i <= 4; i += 1.2) {
      const stripe = new THREE.Mesh(new THREE.BoxGeometry(0.1, 0.05, 2.6), stripeMat);
      stripe.position.set(i, 0.02, 0);
      stripe.receiveShadow = true;
      scene.add(stripe);
    }

    // --- Build low-poly humanoid using simple boxes ---
    // Materials
    const skinMat = new THREE.MeshStandardMaterial({ color: 0x8a5a3a, roughness: 0.7 });
    const shirtMat = new THREE.MeshStandardMaterial({ color: 0x3a8a5a, roughness: 0.7 });
    const pantsMat = new THREE.MeshStandardMaterial({ color: 0x3a5a8a, roughness: 0.7 });
    const shoeMat = new THREE.MeshStandardMaterial({ color: 0x2a2a3a, roughness: 0.9 });

    // Group for the whole figure
    const figure = new THREE.Group();
    figure.position.set(0, 0.2, 0);

    // Torso
    const torso = new THREE.Mesh(new THREE.BoxGeometry(0.9, 1.1, 0.5), shirtMat);
    torso.position.set(0, 1.3, 0);
    torso.castShadow = true;
    figure.add(torso);

    // Head
    const head = new THREE.Mesh(new THREE.BoxGeometry(0.55, 0.55, 0.5), skinMat);
    head.position.set(0, 2.0, 0.05);
    head.castShadow = true;
    figure.add(head);

    // Eyes (simple)
    const eyeMat = new THREE.MeshStandardMaterial({ color: 0x111111 });
    const eyeL = new THREE.Mesh(new THREE.BoxGeometry(0.1, 0.1, 0.05), eyeMat);
    eyeL.position.set(-0.15, 2.05, 0.28);
    figure.add(eyeL);
    const eyeR = new THREE.Mesh(new THREE.BoxGeometry(0.1, 0.1, 0.05), eyeMat);
    eyeR.position.set(0.15, 2.05, 0.28);
    figure.add(eyeR);

    // Hat / hair
    const hatMat = new THREE.MeshStandardMaterial({ color: 0x2a2a3a });
    const hat = new THREE.Mesh(new THREE.BoxGeometry(0.6, 0.2, 0.55), hatMat);
    hat.position.set(0, 2.25, 0.05);
    hat.castShadow = true;
    figure.add(hat);

    // Arms (left and right as groups)
    // Left arm group
    const leftArm = new THREE.Group();
    leftArm.position.set(-0.55, 1.4, 0);
    const leftUpper = new THREE.Mesh(new THREE.BoxGeometry(0.22, 0.6, 0.22), skinMat);
    leftUpper.position.y = 0.3;
    leftUpper.castShadow = true;
    leftArm.add(leftUpper);
    const leftLower = new THREE.Mesh(new THREE.BoxGeometry(0.2, 0.55, 0.2), skinMat);
    leftLower.position.y = -0.25;
    leftLower.castShadow = true;
    leftArm.add(leftLower);
    const leftHand = new THREE.Mesh(new THREE.BoxGeometry(0.18, 0.18, 0.18), skinMat);
    leftHand.position.y = -0.55;
    leftHand.castShadow = true;
    leftArm.add(leftHand);
    figure.add(leftArm);

    // Right arm group
    const rightArm = new THREE.Group();
    rightArm.position.set(0.55, 1.4, 0);
    const rightUpper = new THREE.Mesh(new THREE.BoxGeometry(0.22, 0.6, 0.22), skinMat);
    rightUpper.position.y = 0.3;
    rightUpper.castShadow = true;
    rightArm.add(rightUpper);
    const rightLower = new THREE.Mesh(new THREE.BoxGeometry(0.2, 0.55, 0.2), skinMat);
    rightLower.position.y = -0.25;
    rightLower.castShadow = true;
    rightArm.add(rightLower);
    const rightHand = new THREE.Mesh(new THREE.BoxGeometry(0.18, 0.18, 0.18), skinMat);
    rightHand.position.y = -0.55;
    rightHand.castShadow = true;
    rightArm.add(rightHand);
    figure.add(rightArm);

    // Legs (groups)
    // Left leg
    const leftLeg = new THREE.Group();
    leftLeg.position.set(-0.25, 0.6, 0);
    const leftThigh = new THREE.Mesh(new THREE.BoxGeometry(0.25, 0.6, 0.25), pantsMat);
    leftThigh.position.y = 0.3;
    leftThigh.castShadow = true;
    leftLeg.add(leftThigh);
    const leftShin = new THREE.Mesh(new THREE.BoxGeometry(0.22, 0.55, 0.22), pantsMat);
    leftShin.position.y = -0.25;
    leftShin.castShadow = true;
    leftLeg.add(leftShin);
    const leftFoot = new THREE.Mesh(new THREE.BoxGeometry(0.25, 0.15, 0.4), shoeMat);
    leftFoot.position.set(0, -0.55, 0.1);
    leftFoot.castShadow = true;
    leftLeg.add(leftFoot);
    figure.add(leftLeg);

    // Right leg
    const rightLeg = new THREE.Group();
    rightLeg.position.set(0.25, 0.6, 0);
    const rightThigh = new THREE.Mesh(new THREE.BoxGeometry(0.25, 0.6, 0.25), pantsMat);
    rightThigh.position.y = 0.3;
    rightThigh.castShadow = true;
    rightLeg.add(rightThigh);
    const rightShin = new THREE.Mesh(new THREE.BoxGeometry(0.22, 0.55, 0.22), pantsMat);
    rightShin.position.y = -0.25;
    rightShin.castShadow = true;
    rightLeg.add(rightShin);
    const rightFoot = new THREE.Mesh(new THREE.BoxGeometry(0.25, 0.15, 0.4), shoeMat);
    rightFoot.position.set(0, -0.55, 0.1);
    rightFoot.castShadow = true;
    rightLeg.add(rightFoot);
    figure.add(rightLeg);

    // Add figure to scene
    scene.add(figure);

    // --- Animation state ---
    // Cycle: 0-2s stand, 2-5s walk, 5-8s run, 8-10s stand
    const CYCLE_DURATION = 10;
    let startTime = performance.now() / 1000;

    // Helper to compute phase and state
    function getState(t) {
      const cycleTime = t % CYCLE_DURATION;
      if (cycleTime < 2) return { type: 'stand', local: cycleTime };
      if (cycleTime < 5) return { type: 'walk', local: cycleTime - 2 };
      if (cycleTime < 8) return { type: 'run', local: cycleTime - 5 };
      return { type: 'stand', local: cycleTime - 8 };
    }

    // --- Animation loop ---
    function animate() {
      const now = performance.now() / 1000;
      const elapsed = now - startTime;
      const state = getState(elapsed);

      // Base pose: standing
      let armAngle = 0;
      let legAngle = 0;
      let armSpeed = 0;
      let legSpeed = 0;
      let armAmplitude = 0;
      let legAmplitude = 0;
      let torsoLean = 0; // slight forward lean for run

      if (state.type === 'walk') {
        const p = state.local; // 0..3
        armSpeed = 2.0; // ~2 swings per second
        legSpeed = 2.0;
        armAmplitude = 0.35;
        legAmplitude = 0.35;
        torsoLean = 0.05;
      } else if (state.type === 'run') {
        const p = state.local; // 0..3
        armSpeed = 3.2;
        legSpeed = 3.2;
        armAmplitude = 0.65;
        legAmplitude = 0.65;
        torsoLean = 0.25;
      }

      // Compute swing using sine
      const time = elapsed;
      // For walk/run, use phase based on cycle time
      let armPhase = 0;
      let legPhase = 0;
      if (state.type === 'walk' || state.type === 'run') {
        const speed = state.type === 'walk' ? 2.0 : 3.2;
        armPhase = Math.sin(time * speed * Math.PI * 2);
        legPhase = Math.sin(time * speed * Math.PI * 2 + Math.PI); // opposite phase
      }

      // Apply to arms
      leftArm.rotation.z = armPhase * armAmplitude;
      rightArm.rotation.z = -armPhase * armAmplitude;

      // Apply to legs (rotation.x for forward swing)
      leftLeg.rotation.x = legPhase * legAmplitude;
      rightLeg.rotation.x = -legPhase * legAmplitude;

      // Torso lean (forward for run)
      torso.rotation.x = torsoLean;
      head.rotation.x = torsoLean * 0.8;
      // Reset torso rotation for stand
      if (state.type === 'stand') {
        torso.rotation.x = 0;
        head.rotation.x = 0;
        leftArm.rotation.z = 0;
        rightArm.rotation.z = 0;
        leftLeg.rotation.x = 0;
        rightLeg.rotation.x = 0;
      }

      // Slight bounce for run (vertical bob)
      if (state.type === 'run') {
        figure.position.y = 0.2 + Math.abs(Math.sin(time * 3.2 * Math.PI * 2)) * 0.1;
      } else if (state.type === 'walk') {
        figure.position.y = 0.2 + Math.abs(Math.sin(time * 2.0 * Math.PI * 2)) * 0.04;
      } else {
        figure.position.y = 0.2;
      }

      // Render
      renderer.render(scene, camera);
      requestAnimationFrame(animate);
    }

    // Start animation immediately
    animate();

    // --- Resize handler ---
    window.addEventListener('resize', () => {
      camera.aspect = window.innerWidth / window.innerHeight;
      camera.updateProjectionMatrix();
      renderer.setSize(window.innerWidth, window.innerHeight);
    });
  </script>
</body>
</html>
```
